const body = $json.body ?? $json;

const sessionId = String(
  body.session_id ?? body.sessionId ?? body.conversation_id ?? body.sender_id ?? 'default-session'
).trim();
const rawMessage = String(body.message ?? body.text ?? body.input ?? '').trim();
const message = rawMessage.toLowerCase();

const store = $getWorkflowStaticData('global');
if (!store.sessions) store.sessions = {};

function newSession() {
  return {
    stage: 'new',
    name: null,
    date: null,
    time_preference: null,
    confirmed: false
  };
}

if (!store.sessions[sessionId]) {
  store.sessions[sessionId] = newSession();
}
let session = store.sessions[sessionId];

const serviceQuestion = /what services|which services|services do you offer|what do you offer|help with/.test(message);
const cancelIntent = /(^|\\b)(cancel|stop|never mind|nevermind)(\\b|$)/.test(message);
const restartIntent = /book again|new booking|another appointment|start over/.test(message);

if (body.reset === true || message === '__reset__') {
  store.sessions[sessionId] = newSession();
  return [{ json: { reply: 'Session reset. How can I help you today?', session_id: sessionId, stage: 'new' } }];
}

if (cancelIntent) {
  store.sessions[sessionId] = newSession();
  return [{ json: { reply: 'Your booking has been cancelled.', session_id: sessionId, stage: 'new' } }];
}

if (restartIntent) {
  store.sessions[sessionId] = { ...newSession(), stage: 'awaiting_name' };
  return [{ json: { reply: "Sure. What's your name?", session_id: sessionId, stage: 'awaiting_name' } }];
}

if (serviceQuestion) {
  let resume = '';
  if (session.stage === 'awaiting_name') resume = " What's your name?";
  if (session.stage === 'awaiting_date') resume = ' What date would you like your appointment?';
  if (session.stage === 'awaiting_time') resume = ' Would you prefer Morning or Afternoon?';
  return [{
    json: {
      reply: 'We offer Website Development, Automation Consulting, and AI Consulting.' + resume,
      session_id: sessionId,
      stage: session.stage
    }
  }];
}

if (session.stage === 'new') {
  session.stage = 'awaiting_name';
  return [{ json: { reply: "Sure! What's your name?", session_id: sessionId, stage: session.stage } }];
}

if (session.stage === 'awaiting_name') {
  const cleaned = rawMessage
    .replace(/^(my name is|i am|i'm|im|this is)\\s+/i, '')
    .replace(/[.!?]+$/g, '')
    .trim();
  if (!cleaned || cleaned.length < 2 || cleaned.length > 60) {
    return [{ json: { reply: "I didn't catch your name. What's your name?", session_id: sessionId, stage: session.stage } }];
  }
  session.name = cleaned;
  session.stage = 'awaiting_date';
  return [{ json: { reply: `Thanks, ${session.name}. What date would you like your appointment?`, session_id: sessionId, stage: session.stage } }];
}

if (session.stage === 'awaiting_date') {
  const clearDate = /\\b(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday|jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\\b/i.test(rawMessage)
    || /\\b\\d{1,2}[\\/-]\\d{1,2}(?:[\\/-]\\d{2,4})?\\b/.test(rawMessage)
    || /\\b\\d{1,2}(?:st|nd|rd|th)\\b/i.test(rawMessage);
  const vagueDate = /sometime|whenever|later|not sure|maybe|any day|one day/i.test(rawMessage);
  if (!clearDate || vagueDate) {
    return [{ json: { reply: 'Please give me a specific appointment date.', session_id: sessionId, stage: session.stage } }];
  }
  session.date = rawMessage.replace(/[.!?]+$/g, '').trim();
  session.stage = 'awaiting_time';
  return [{ json: { reply: 'Would you prefer Morning or Afternoon?', session_id: sessionId, stage: session.stage } }];
}

if (session.stage === 'awaiting_time') {
  const wantsMorning = /\\bmorning\\b/i.test(rawMessage);
  const wantsAfternoon = /\\bafternoon\\b/i.test(rawMessage);
  if (!wantsMorning && !wantsAfternoon) {
    return [{ json: { reply: 'Please choose Morning or Afternoon.', session_id: sessionId, stage: session.stage } }];
  }
  session.time_preference = wantsMorning ? 'Morning' : 'Afternoon';
  session.confirmed = true;
  session.stage = 'confirmed';
  return [{
    json: {
      reply: `Your appointment is confirmed for ${session.name} on ${session.date} in the ${session.time_preference}.`,
      session_id: sessionId,
      stage: session.stage
    }
  }];
}

return [{
  json: {
    reply: `Your appointment is already confirmed for ${session.name} on ${session.date} in the ${session.time_preference}. Say "book again" to start a new booking or "cancel" to cancel.`,
    session_id: sessionId,
    stage: session.stage
  }
}];
